import {
  faBlog,
  faCalendarDays,
  faChevronUp,
  faClockRotateLeft,
  faClose,
  faCookie,
  faCookieBite,
  faFolder,
  faHeart,
  faLaptopCode,
  faNavicon,
  faPenNib,
  faPersonRays,
  faRainbow,
  faSearch,
  faTag,
  faTags,
  faWarning,
} from "@fortawesome/free-solid-svg-icons";
